def _cmd_email(args: str) -> dict:
    """Delegate to the Yubin email fetch pipeline."""
    hours = "24"
    if "--hours" in args:
        hours = args.split("--hours")[1].strip().split()[0]
    return {
        "command": "/email", "agent": "yubin", "status": "delegated",
        "response": f"📧 Delegating to Yubin — fetching last {hours}h...",
        "execute": f"bash {SCRIPTS_DIR}/yubin/yubin-daily.sh --hours {hours}",
    }
